import type { AuthError, Session, SupabaseClient, User } from '@supabase/supabase-js';
import { sanitizeEmail, sanitizePasswordForSignIn } from '@/lib/auth-helpers';

export type EmailPasswordSignInCredentials = {
  email: string;
  passwordLength: number;
};

export type EmailPasswordSignInSuccess = {
  ok: true;
  session: Session;
  user: User;
  credentials: EmailPasswordSignInCredentials;
  usedFallback: boolean;
};

export type EmailPasswordSignInFailure = {
  ok: false;
  error: AuthError;
  credentials: EmailPasswordSignInCredentials;
};

export type EmailPasswordSignInResult = EmailPasswordSignInSuccess | EmailPasswordSignInFailure;

/**
 * Single path for email/password sign-in: normalize inputs → Supabase password grant only.
 * No owner/MFA/session side effects (handle those in AuthProvider after this returns).
 *
 * FALLBACK: When Supabase GoTrue is degraded (522/timeout), falls back to the IVX backend
 * direct-auth endpoint (/api/ivx/auth/direct-sign-in) which verifies the password directly
 * against the Postgres auth.users table and mints a Supabase-compatible JWT.
 */
/**
 * Enterprise auth trace ID for diagnostics (Phase 6).
 * Format: auth-<timestamp>-<random6> — never contains password data.
 */
export function generateAuthTraceId(): string {
  return `auth-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
}

/** Resolve the IVX backend API base URL for the direct-auth fallback. */
function getBackendApiBase(): string {
  const fromEnv = (process.env.EXPO_PUBLIC_API_BASE_URL || process.env.EXPO_PUBLIC_IVX_API_BASE_URL || '').trim().replace(/\/+$/, '');
  return fromEnv || 'https://api.ivxholding.com';
}

/**
 * Call the IVX backend direct-auth endpoint (GoTrue bypass).
 * Returns a Supabase-compatible session on success.
 */
async function directAuthFallback(
  email: string,
  password: string,
  client: SupabaseClient,
  traceId: string,
): Promise<EmailPasswordSignInResult | null> {
  const baseUrl = getBackendApiBase();
  const endpoint = `${baseUrl}/api/ivx/auth/direct-sign-in`;
  const credentials: EmailPasswordSignInCredentials = { email, passwordLength: password.length };

  try {
    const controller = new AbortController();
    const timeout = setTimeout(() => controller.abort(), 20000);

    const response = await fetch(endpoint, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ email, password }),
      signal: controller.signal,
    }).finally(() => clearTimeout(timeout));

    if (!response.ok) {
      const body = await response.json().catch(() => ({})) as Record<string, unknown>;
      const errorMsg = typeof body.error === 'string' ? body.error : `Direct auth failed (HTTP ${response.status}).`;
      console.log(`[Auth] Direct-auth fallback failed traceId=${traceId} status=${response.status} email=${email}`);
      const error: AuthError = {
        name: 'AuthError',
        message: errorMsg,
        status: response.status,
        code: 'direct_auth_failed',
      } as AuthError;
      return { ok: false, error, credentials };
    }

    const data = await response.json() as {
      ok: boolean;
      access_token: string;
      refresh_token: string;
      expires_at: number;
      user: Record<string, unknown>;
    };

    if (!data.ok || !data.access_token || !data.refresh_token) {
      console.log(`[Auth] Direct-auth returned incomplete data traceId=${traceId} email=${email}`);
      return null; // Let caller handle as a regular failure
    }

    // Use supabase.auth.setSession() to install the tokens into the Supabase client,
    // so the rest of the app (RLS, realtime, etc.) works normally.
    const { data: sessionData, error: sessionError } = await client.auth.setSession({
      access_token: data.access_token,
      refresh_token: data.refresh_token,
    });

    if (sessionError || !sessionData.session || !sessionData.user) {
      console.log(`[Auth] Direct-auth setSession failed traceId=${traceId} error=${sessionError?.message ?? 'no session'} email=${email}`);
      const error: AuthError = {
        name: 'AuthError',
        message: sessionError?.message ?? 'Failed to install direct-auth session.',
        status: 500,
        code: 'direct_auth_setsession_failed',
      } as AuthError;
      return { ok: false, error, credentials };
    }

    console.log(`[Auth] Direct-auth fallback succeeded traceId=${traceId} email=${email} user=${sessionData.user.id}`);
    return {
      ok: true,
      session: sessionData.session,
      user: sessionData.user,
      credentials,
      usedFallback: true,
    };
  } catch (error) {
    console.log(`[Auth] Direct-auth fallback error traceId=${traceId} error=${(error as Error)?.message ?? 'unknown'} email=${email}`);
    return null; // null means "couldn't determine result" — caller falls through to original error
  }
}

export async function signInWithEmailPassword(
  client: SupabaseClient,
  rawEmail: string,
  rawPassword: string,
): Promise<EmailPasswordSignInResult> {
  const email = sanitizeEmail(rawEmail);
  const password = sanitizePasswordForSignIn(rawPassword);
  const credentials: EmailPasswordSignInCredentials = {
    email,
    passwordLength: password.length,
  };
  const traceId = generateAuthTraceId();

  // First attempt: Supabase GoTrue with retries (handled in supabase.ts fetch layer).
  // Timeout at 20s — if GoTrue is degraded, we fall back to the backend direct-auth
  // endpoint rather than waiting for all 3 retries (which could take 40+ seconds).
  const GOTRUE_TIMEOUT_MS = 20000;

  const signInPromise = client.auth.signInWithPassword({ email, password });
  const timeoutPromise = new Promise<never>((_, reject) => {
    const timeout = setTimeout(() => {
      const synthetic: AuthError = {
        name: 'AuthError',
        message: 'GoTrue timeout',
        status: 408,
        code: 'gotrue_timeout',
      } as AuthError;
      reject(synthetic);
    }, GOTRUE_TIMEOUT_MS);
    signInPromise.then(() => clearTimeout(timeout)).catch(() => clearTimeout(timeout));
  });

  let gotrueResult: { data: { session: Session | null; user: User | null }; error: AuthError | null } | null = null;
  let gotrueTimedOut = false;

  try {
    gotrueResult = await Promise.race([
      signInPromise as Promise<{ data: { session: Session | null; user: User | null }; error: AuthError | null }>,
      timeoutPromise,
    ]);
  } catch (timeoutError) {
    gotrueTimedOut = true;
    console.log(`[Auth] GoTrue timed out after ${GOTRUE_TIMEOUT_MS}ms, trying direct-auth fallback traceId=${traceId} email=${email}`);
  }

  // If GoTrue succeeded, return the result
  if (gotrueResult && !gotrueResult.error && gotrueResult.data.session && gotrueResult.data.user) {
    console.log(`[Auth] Sign-in succeeded via GoTrue traceId=${traceId} email=${email}`);
    return {
      ok: true,
      session: gotrueResult.data.session,
      user: gotrueResult.data.user,
      credentials,
      usedFallback: false,
    };
  }

  // If GoTrue returned a real auth error (not timeout/network), don't fallback —
  // the credentials are just wrong and we should show the proper error.
  if (gotrueResult && gotrueResult.error && !gotrueTimedOut) {
    const authError = gotrueResult.error as AuthError & { status?: number; code?: string };
    const isGoTrueDegraded = authError.message === 'Aborted'
      || authError.name === 'AbortError'
      || authError.status === 503
      || authError.status === 522
      || authError.status === 524
      || authError.status === 502
      || authError.code === 'auth_server_unreachable';

    if (!isGoTrueDegraded) {
      // Real auth error (invalid credentials, email not confirmed, etc.) — return it directly
      console.log(`[Auth] Sign-in failed traceId=${traceId} code=${authError.code ?? 'unknown'} status=${authError.status ?? 'unknown'} email=${email}`);
      return { ok: false, error: gotrueResult.error, credentials };
    }

    // GoTrue is degraded — fall through to direct-auth fallback
    console.log(`[Auth] GoTrue degraded (${authError.status ?? authError.code}), trying direct-auth fallback traceId=${traceId} email=${email}`);
  }

  // ── FALLBACK: Backend direct-auth (GoTrue bypass) ─────────────────────────
  const fallbackResult = await directAuthFallback(email, password, client, traceId);
  if (fallbackResult) {
    return fallbackResult;
  }

  // If fallback also couldn't determine a result, return a user-friendly error
  const friendly: AuthError = {
    name: 'AuthError',
    message: gotrueTimedOut
      ? 'Sign-in timed out. The auth server and fallback are both temporarily unavailable. Please try again in a few minutes.'
      : 'Unable to complete sign-in. Please check your credentials and try again.',
    status: 503,
    code: 'all_auth_paths_failed',
  } as AuthError;
  console.log(`[Auth] All sign-in paths exhausted traceId=${traceId} email=${email}`);
  return { ok: false, error: friendly, credentials };
}

