CREATE OR REPLACE FUNCTION public.ivx_query_auth_user_by_email(user_email TEXT)
RETURNS JSON AS $fn$
BEGIN
  RETURN (
    SELECT json_build_object(
      'id', u.id::text,
      'email', u.email,
      'encrypted_password', u.encrypted_password,
      'email_confirmed_at', u.email_confirmed_at,
